var pw = await import("playwright");
var browserV = await pw.chromium.launch({headless:true});
var pageV = await browserV.newPage({viewport:{width:1440,height:900},deviceScaleFactor:1});
var errorsV = [];
pageV.on("pageerror", function(error){ errorsV.push("page: " + error.message); });
pageV.on("console", function(message){ if(message.type()==="error") errorsV.push("console: " + message.text()); });
await pageV.goto("file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/air-conditioning-understanding/2026-07-15-codex-gpt-5-6-sol/index.html",{waitUntil:"domcontentloaded"});
await pageV.waitForTimeout(5500);
var initialV = await pageV.evaluate(function(){
  return {
    ready:window.__hvacReady,
    title:document.title,
    heading:document.querySelector("h1").textContent,
    canvas:!!document.querySelector("#scene canvas"),
    fallbackVisible:document.getElementById("fallback").classList.contains("visible"),
    system:document.getElementById("state-title").textContent,
    mode:document.getElementById("mode-pill").textContent,
    visibleLabels:document.querySelectorAll(".callout.visible").length
  };
});
await pageV.click('[data-system="mono"]');
await pageV.click('[data-mode="heating"]');
var switchedV = await pageV.evaluate(function(){
  return {
    system:document.getElementById("state-title").textContent,
    mode:document.getElementById("mode-pill").textContent,
    absorbed:document.getElementById("absorbed").textContent,
    released:document.getElementById("released").textContent,
    roomTemp:document.getElementById("room-temp").textContent,
    monoPressed:document.querySelector('[data-system="mono"]').getAttribute("aria-pressed")
  };
});
await pageV.click("#play-btn");
var pausedV = await pageV.getAttribute("#play-btn","aria-label");
await pageV.click("#reset-btn");
await pageV.click("#guide-btn");
var tourV = await pageV.evaluate(function(){
  return {
    open:document.getElementById("tour-card").classList.contains("open"),
    step:document.getElementById("tour-count").textContent,
    title:document.getElementById("tour-title").textContent
  };
});
await pageV.click("#tour-next");
var nextV = await pageV.textContent("#tour-count");
await browserV.close();
nodeRepl.write(JSON.stringify({initial:initialV,switched:switchedV,pausedLabel:pausedV,tour:tourV,nextStep:nextV,errors:errorsV},null,2));

